4	const supabaseAnonKey = import.meta.env.VITE_SUPABASE_ANON_KEY as string;
5	
6	if (!supabaseUrl || !supabaseAnonKey) {
7	  throw new Error(
8	    "Missing Supabase environment variables. Set VITE_SUPABASE_URL and VITE_SUPABASE_ANON_KEY."
