1	import { useState, useEffect, useCallback, useId } from "react";
2	import { useNavigate, useSearchParams } from "react-router-dom";
3	import {
4	  ScanLine,
5	  Info,
6	  AlertCircle,
7	  CheckCircle2,
8	  Loader2,
9	  Globe,
10	  ArrowRight,
11	} from "lucide-react";
12	import { Card, CardContent } from "@/components/ui/card";
13	import { Button } from "@/components/ui/button";
14	import { Input } from "@/components/ui/input";
15	import { Progress } from "@/components/ui/progress";
16	import { Badge } from "@/components/ui/badge";
17	import {
18	  Select,
19	  SelectContent,
20	  SelectItem,
21	  SelectTrigger,
22	  SelectValue,
23	} from "@/components/ui/select";
24	import { ScanProgressTimeline } from "@/components/shared/ScanProgressTimeline";
25	import { BrowserFrame } from "@/components/shared/BrowserFrame";
26	import { PageTransition } from "@/components/shared/PageTransition";
27	import { CRO_PILLARS, SCAN_STEPS, PAGE_TYPES } from "@/lib/constants";
28	import { MOCK_USER } from "@/lib/mock-data";
29	import type { PageType } from "@/types";
30	import { cn } from "@/lib/utils";
31	
32	/** Basic URL validation — checks structure, not reachability */
33	function isValidUrl(str: string): boolean {
34	  try {
35	    const url = new URL(str.startsWith("http") ? str : `https://${str}`);
36	    return url.protocol === "https:" || url.protocol === "http:";
37	  } catch {
38	    return false;
39	  }
40	}
41	
42	/** Normalize URL: prepend https:// if missing */
43	function normalizeUrl(str: string): string {
44	  const trimmed = str.trim();
45	  if (!trimmed) return trimmed;
46	  if (/^https?:\/\//i.test(trimmed)) return trimmed;
47	  return `https://${trimmed}`;
48	}
49	
50	/** Generate a random-looking scan ID */
51	function generateScanId(): string {
52	  const chars = "abcdefghijklmnopqrstuvwxyz0123456789";
53	  let id = "sc_";
54	  for (let i = 0; i < 6; i++) id += chars[Math.floor(Math.random() * chars.length)];
55	  return id;
56	}
57	
58	const Scan = () => {
59	  const navigate = useNavigate();
60	  const [searchParams] = useSearchParams();
61	  const [rawUrl, setRawUrl] = useState(searchParams.get("url") || "");
62	  const [pageType, setPageType] = useState<PageType>(
63	    (searchParams.get("type") as PageType) || "landing"
64	  );
65	  const [isAnalyzing, setIsAnalyzing] = useState(false);
66	  const [currentStep, setCurrentStep] = useState(-1);
67	  const [urlError, setUrlError] = useState<string | null>(null);
68	  const [scanId] = useState(generateScanId);
69	  const inputId = useId();
70	
71	  const totalSteps = SCAN_STEPS.length;
72	  const progressPercent = currentStep < 0 ? 0 : Math.round(((currentStep + 1) / totalSteps) * 100);
73	  const normalizedUrl = normalizeUrl(rawUrl);
74	  const user = MOCK_USER;
75	  const scansRemaining = user.scan_limit - user.scans_used;
76	  const atLimit = scansRemaining <= 0;
77	
78	  const startAnalysis = useCallback(() => {
79	    setUrlError(null);
80	    if (!rawUrl.trim()) {
81	      setUrlError("Please enter a URL.");
82	      return;
83	    }
84	    if (!isValidUrl(normalizedUrl)) {
85	      setUrlError("Enter a valid URL like https://example.com/page");
86	      return;
87	    }
88	    if (atLimit) return;
89	    setIsAnalyzing(true);
90	    setCurrentStep(0);
91	  }, [rawUrl, normalizedUrl, atLimit]);
92	
93	  // Step progression
94	  useEffect(() => {
95	    if (!isAnalyzing || currentStep < 0) return;
96	    if (currentStep >= totalSteps) {
97	      // Navigate to demo report (first completed scan with pillar data)
98	      const timer = setTimeout(() => navigate(`/reports/sc_7x9kp2`, { state: { scannedUrl: normalizedUrl, pageType } }), 800);
99	      return () => clearTimeout(timer);
100	    }
101	    // Varying step durations to feel more realistic
102	    const durations = [900, 1400, 1200, 1100, 1300, 1000, 1600];
103	    const timer = setTimeout(() => setCurrentStep((prev) => prev + 1), durations[currentStep] ?? 1200);
104	    return () => clearTimeout(timer);
105	  }, [isAnalyzing, currentStep, totalSteps, navigate]);
106	
107	  const handleSubmit = (e: React.FormEvent) => {
108	    e.preventDefault();
109	    startAnalysis();
110	  };
111	
112	  // ── Analysis Progress View ──────────────────────────────────
113	  if (isAnalyzing) {
114	    const hostname = (() => { try { return new URL(normalizedUrl).hostname; } catch { return rawUrl; } })();
115	    return (
116	      <PageTransition>
117	        <div className="mx-auto max-w-2xl space-y-6">
118	          <div>
119	            <h2 className="text-[28px] font-bold text-foreground">Analyzing your page</h2>
120	            <p className="mt-1 text-sm text-muted-foreground">
121	              Scanning <span className="font-medium text-foreground">{hostname}</span> — this usually takes 20-40 seconds
122	            </p>
123	          </div>
124	
125	          {/* Progress bar */}
126	          <div className="space-y-1.5">
127	            <div className="flex items-center justify-between text-sm">
128	              <span className="text-muted-foreground">
129	                Step {Math.min(currentStep + 1, totalSteps)} of {totalSteps}
130	              </span>
131	              <span className="tabular-nums font-medium text-foreground">{Math.min(progressPercent, 100)}%</span>
132	            </div>
133	            <Progress value={Math.min(progressPercent, 100)} className="h-2" />
134	          </div>
135	
136	          {/* Browser frame */}
137	          <BrowserFrame url={normalizedUrl}>
138	            <div className="relative flex h-52 items-center justify-center bg-gradient-to-br from-slate-50 via-white to-slate-50">
139	              {/* Scanning animation */}
140	              <div className="absolute inset-x-0 top-0 h-1 overflow-hidden">
141	                <div className="h-full w-1/3 animate-[shimmer_1.5s_ease-in-out_infinite] bg-gradient-to-r from-transparent via-primary/30 to-transparent" />
142	              </div>
143	              <div className="text-center">
144	                <Loader2 className="mx-auto mb-3 h-8 w-8 animate-spin text-primary" />
145	                <p className="text-sm font-medium text-muted-foreground">
146	                  {currentStep < totalSteps ? SCAN_STEPS[currentStep]?.label : "Finalizing report"}...
147	                </p>
148	              </div>
149	            </div>
150	          </BrowserFrame>
151	
152	          {/* Timeline */}
153	          <Card className="border-slate-200 shadow-none">
154	            <CardContent className="p-6">
155	              <ScanProgressTimeline steps={SCAN_STEPS} currentStep={currentStep} />
156	            </CardContent>
157	          </Card>
158	        </div>
159	      </PageTransition>
160	    );
161	  }
162	
163	  // ── URL Input Form ──────────────────────────────────────────
164	  return (
165	    <PageTransition>
166	      <div className="mx-auto max-w-2xl space-y-8">
167	        <div className="text-center">
168	          <h2 className="text-[28px] font-bold text-foreground">Analyze your page</h2>
169	          <p className="mt-2 text-muted-foreground">
170	            Enter any URL to get a detailed CRO audit with actionable recommendations
171	          </p>
172	        </div>
173	
174	        {/* URL Input Card */}
175	        <Card className="border-slate-200 shadow-none">
176	          <CardContent className="p-8">
177	            <form onSubmit={handleSubmit} className="space-y-4">
178	              <div>
179	                <label htmlFor={inputId} className="mb-1.5 block text-sm font-medium text-foreground">
180	                  Page URL
