import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import supabase from "@/lib/supabase";
import { useAuth } from "@/contexts/AuthContext";
import type { UserProfile } from "@/types";
import type { ProfileUpdate } from "@/types/database";

// ── Query keys ──────────────────────────────────────────────────

export const profileKeys = {
  all: ["profile"] as const,
  byUser: (userId: string) => ["profile", userId] as const,
};

// ── useProfile ──────────────────────────────────────────────────

export function useProfile() {
  const { user } = useAuth();

  return useQuery({
    queryKey: profileKeys.byUser(user?.id ?? ""),
    queryFn: async (): Promise<UserProfile | null> => {
      if (!user?.id) return null;

      const { data, error } = await supabase
        .from("profiles")
        .select(
          "id, email, full_name, company_name, website_url, avatar_url, plan, scans_used, scan_limit, created_at, billing_cycle_end"
        )
        .eq("id", user.id)
        .single();

      if (error) {
        if (error.code === "PGRST116") return null; // row not found
        throw new Error(error.message);
      }

      return data as UserProfile;
    },
    enabled: !!user?.id,
    staleTime: 1000 * 60 * 2, // 2 minutes
  });
}

// ── useUpdateProfile ────────────────────────────────────────────

type ProfileUpdatableFields = Pick<
  ProfileUpdate,
  "full_name" | "company_name" | "website_url" | "avatar_url"
>;

export function useUpdateProfile() {
  const { user, refreshProfile } = useAuth();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (updates: ProfileUpdatableFields) => {
      if (!user?.id) throw new Error("Not authenticated");

      const { data, error } = await supabase
        .from("profiles")
        .update({ ...updates, updated_at: new Date().toISOString() })
        .eq("id", user.id)
        .select(
          "id, email, full_name, company_name, website_url, avatar_url, plan, scans_used, scan_limit, created_at, billing_cycle_end"
        )
        .single();

      if (error) throw new Error(error.message);
      return data as UserProfile;
    },
    onSuccess: (data) => {
      // Update React Query cache
      if (user?.id) {
        queryClient.setQueryData(profileKeys.byUser(user.id), data);
      }
      // Also refresh the AuthContext profile so header/sidebar updates
      refreshProfile();
    },
  });
}

import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import supabase from "@/lib/supabase";
import { useAuth } from "@/contexts/AuthContext";
import type { Scan, PageType } from "@/types";
import type { ScanRow } from "@/types/database";

// ── Query keys ──────────────────────────────────────────────────

export const scanKeys = {
  all: ["scans"] as const,
  lists: () => [...scanKeys.all, "list"] as const,
  list: (userId: string) => [...scanKeys.lists(), userId] as const,
  details: () => [...scanKeys.all, "detail"] as const,
  detail: (id: string) => [...scanKeys.details(), id] as const,
};

// ── Row → App type mapper ───────────────────────────────────────

function rowToScan(row: ScanRow): Scan {
  return {
    id: row.id,
    user_id: row.user_id,
    url: row.url,
    favicon_url: row.favicon_url,
    page_title: row.page_title,
    page_type: row.page_type,
    status: row.status,
    overall_score: row.overall_score,
    issues_found: row.issues_found,
    critical_issues: row.critical_issues,
    warnings: row.warnings,
    quick_wins: row.quick_wins,
    screenshot_url: row.screenshot_url,
    device: row.device,
    created_at: row.created_at,
    completed_at: row.completed_at,
  };
}

// ── useScans ────────────────────────────────────────────────────

export function useScans() {
  const { user } = useAuth();

  return useQuery({
    queryKey: scanKeys.list(user?.id ?? ""),
    queryFn: async (): Promise<Scan[]> => {
      if (!user?.id) return [];

      const { data, error } = await supabase
        .from("scans")
        .select("*")
        .eq("user_id", user.id)
        .order("created_at", { ascending: false });

      if (error) throw new Error(error.message);
      return (data as ScanRow[]).map(rowToScan);
    },
    enabled: !!user?.id,
    staleTime: 1000 * 30, // 30 seconds
  });
}

// ── useScan ─────────────────────────────────────────────────────

export function useScan(id: string | undefined, options?: { refetchInterval?: number | false }) {
  const { user } = useAuth();

  return useQuery({
    queryKey: scanKeys.detail(id ?? ""),
    queryFn: async (): Promise<Scan | null> => {
      if (!id || !user?.id) return null;

      const { data, error } = await supabase
        .from("scans")
        .select("*")
        .eq("id", id)
        .eq("user_id", user.id)
        .single();

      if (error) {
        if (error.code === "PGRST116") return null;
        throw new Error(error.message);
      }

      return rowToScan(data as ScanRow);
    },
    enabled: !!id && !!user?.id,
    refetchInterval: options?.refetchInterval,
    staleTime: 0,
  });
}

// ── useCreateScan ───────────────────────────────────────────────

interface CreateScanInput {
  url: string;
  page_type: PageType;
}

export function useCreateScan() {
  const { user, refreshProfile } = useAuth();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({ url, page_type }: CreateScanInput): Promise<Scan> => {
      if (!user?.id) throw new Error("Not authenticated");

      // Insert the scan row first
      const { data: scanData, error: insertError } = await supabase
        .from("scans")
        .insert({
          user_id: user.id,
          url,
          page_type,
          status: "pending" as const,
        })
        .select("*")
        .single();

      if (insertError) throw new Error(insertError.message);

      const scan = rowToScan(scanData as ScanRow);

      // Invoke edge function — fire and don't block the return
      // The edge function updates the scan row when done
      supabase.functions
        .invoke("analyze-url", {
          body: { scan_id: scan.id, url, page_type },
        })
        .catch((err: unknown) => {
          console.error("Edge function invocation failed:", err);
        });

      return scan;
    },
    onSuccess: (data) => {
      if (!user?.id) return;
      // Optimistically prepend the new scan to the list cache
      queryClient.setQueryData<Scan[]>(scanKeys.list(user.id), (prev) =>
        prev ? [data, ...prev] : [data]
      );
      // Prime the detail cache
      queryClient.setQueryData(scanKeys.detail(data.id), data);
      // Refresh profile to show updated scans_used count
      refreshProfile();
    },
  });
}

// ── useDeleteScan ───────────────────────────────────────────────

export function useDeleteScan() {
  const { user } = useAuth();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (scanId: string): Promise<void> => {
      if (!user?.id) throw new Error("Not authenticated");

      const { error } = await supabase
        .from("scans")
        .delete()
        .eq("id", scanId)
        .eq("user_id", user.id);

      if (error) throw new Error(error.message);
    },
    onSuccess: (_data, scanId) => {
      if (!user?.id) return;
      // Remove from list cache
      queryClient.setQueryData<Scan[]>(scanKeys.list(user.id), (prev) =>
        prev ? prev.filter((s) => s.id !== scanId) : []
      );
      // Remove detail cache
      queryClient.removeQueries({ queryKey: scanKeys.detail(scanId) });
    },
  });
}

// ── useRefreshScan ──────────────────────────────────────────────
// Creates a new scan for the same URL/page_type as an existing scan

export function useRefreshScan() {
  const createScan = useCreateScan();

  return useMutation({
    mutationFn: async (sourceScan: Pick<Scan, "url" | "page_type">): Promise<Scan> => {
      return createScan.mutateAsync({ url: sourceScan.url, page_type: sourceScan.page_type });
    },
  });
}

import { useQuery } from "@tanstack/react-query";
import supabase from "@/lib/supabase";
import { useAuth } from "@/contexts/AuthContext";
import type { PillarResult, Finding } from "@/types";
import type { ScanResultRow, DbFinding } from "@/types/database";

// ── Query keys ──────────────────────────────────────────────────

export const scanResultKeys = {
  all: ["scan-results"] as const,
  byScan: (scanId: string) => ["scan-results", scanId] as const,
};

// ── Row → App type mapper ───────────────────────────────────────

function dbFindingToFinding(f: DbFinding): Finding {
  return {
    id: f.id,
    title: f.title,
    severity: f.severity,
    current_state: f.current_state,
    recommendation: f.recommendation,
    ai_suggestion: f.ai_suggestion,
    is_premium: f.is_premium,
    effort: f.effort,
    estimated_lift: f.estimated_lift,
    category: f.category,
  };
}

function rowToPillarResult(row: ScanResultRow): PillarResult {
  return {
    id: row.id,
    scan_id: row.scan_id,
    pillar: row.pillar,
    score: row.score,
    weight: row.weight,
    benchmark: row.benchmark,
    findings: (row.findings ?? []).map(dbFindingToFinding),
  };
}

// ── useScanResults ──────────────────────────────────────────────

export function useScanResults(scanId: string | undefined) {
  const { user } = useAuth();

  return useQuery({
    queryKey: scanResultKeys.byScan(scanId ?? ""),
    queryFn: async (): Promise<PillarResult[]> => {
      if (!scanId || !user?.id) return [];

      const { data, error } = await supabase
        .from("scan_results")
        .select("*")
        .eq("scan_id", scanId);

      if (error) throw new Error(error.message);
      return (data as ScanResultRow[]).map(rowToPillarResult);
    },
    enabled: !!scanId && !!user?.id,
    staleTime: 1000 * 60 * 5, // 5 minutes — results don't change after a scan completes
  });
}

import { useQuery } from "@tanstack/react-query";
import supabase from "@/lib/supabase";
import { useAuth } from "@/contexts/AuthContext";
import type { DashboardStats, Scan, Finding } from "@/types";
import type { ScanRow, ScanResultRow, DbFinding } from "@/types/database";

// ── Derived types for dashboard ─────────────────────────────────

export interface ScoreTrendPoint {
  week: string;
  score: number;
}

export interface ScoreDistributionBucket {
  range: string;
  count: number;
  fill: string;
}

export interface DashboardData {
  stats: DashboardStats;
  recentScans: Scan[];
  scoreTrend: ScoreTrendPoint[];
  scoreDistribution: ScoreDistributionBucket[];
  topQuickWins: (Finding & { pillar: string })[];
  latestScanId: string | null;
}

// ── Defaults (empty state) ──────────────────────────────────────

const EMPTY_DASHBOARD: DashboardData = {
  stats: {
    total_scans: 0,
    avg_score: 0,
    total_issues: 0,
    critical_issues: 0,
    estimated_revenue_impact: 0,
    score_trend: 0,
    scans_trend: 0,
    quick_wins: 0,
  },
  recentScans: [],
  scoreTrend: [],
  scoreDistribution: [
    { range: "0-20", count: 0, fill: "#EF4444" },
    { range: "21-40", count: 0, fill: "#F87171" },
    { range: "41-60", count: 0, fill: "#F59E0B" },
    { range: "61-80", count: 0, fill: "#22C55E" },
    { range: "81-100", count: 0, fill: "#16A34A" },
  ],
  topQuickWins: [],
  latestScanId: null,
};

// ── Helpers ─────────────────────────────────────────────────────

function getWeekLabel(date: Date): string {
  const now = new Date();
  const diffMs = now.getTime() - date.getTime();
  const diffWeeks = Math.floor(diffMs / (1000 * 60 * 60 * 24 * 7));
  if (diffWeeks === 0) return "This week";
  if (diffWeeks === 1) return "1w ago";
  return `${diffWeeks}w ago`;
}

function getBucketFill(range: string): string {
  const fills: Record<string, string> = {
    "0-20": "#EF4444",
    "21-40": "#F87171",
    "41-60": "#F59E0B",
    "61-80": "#22C55E",
    "81-100": "#16A34A",
  };
  return fills[range] ?? "#94A3B8";
}

function scoreToRange(score: number): string {
  if (score <= 20) return "0-20";
  if (score <= 40) return "21-40";
  if (score <= 60) return "41-60";
  if (score <= 80) return "61-80";
  return "81-100";
}

function rowToScan(row: ScanRow): Scan {
  return {
    id: row.id,
    user_id: row.user_id,
    url: row.url,
    favicon_url: row.favicon_url,
    page_title: row.page_title,
    page_type: row.page_type,
    status: row.status,
    overall_score: row.overall_score,
    issues_found: row.issues_found,
    critical_issues: row.critical_issues,
    warnings: row.warnings,
    quick_wins: row.quick_wins,
    screenshot_url: row.screenshot_url,
    device: row.device,
    created_at: row.created_at,
    completed_at: row.completed_at,
  };
}

// ── useDashboardStats ───────────────────────────────────────────

export function useDashboardStats() {
  const { user } = useAuth();

  return useQuery({
    queryKey: ["dashboard-stats", user?.id ?? ""],
    queryFn: async (): Promise<DashboardData> => {
      if (!user?.id) return EMPTY_DASHBOARD;

      // Fetch all completed scans for the user
      const { data: scansData, error: scansError } = await supabase
        .from("scans")
        .select("*")
        .eq("user_id", user.id)
        .order("created_at", { ascending: false });

      if (scansError) throw new Error(scansError.message);

      const scans = (scansData as ScanRow[]).map(rowToScan);

      if (scans.length === 0) return EMPTY_DASHBOARD;

      const completedScans = scans.filter((s) => s.status === "completed" && s.overall_score !== null);
      const recentScans = scans.slice(0, 5);
      const latestScanId = completedScans[0]?.id ?? null;

      // ── Stats aggregation ─────────────────────────────────────

      const now = new Date();
      const monthStart = new Date(now.getFullYear(), now.getMonth(), 1);
      const lastMonthStart = new Date(now.getFullYear(), now.getMonth() - 1, 1);

      const scansThisMonth = completedScans.filter(
        (s) => new Date(s.created_at) >= monthStart
      );
      const scansLastMonth = completedScans.filter(
        (s) =>
          new Date(s.created_at) >= lastMonthStart &&
          new Date(s.created_at) < monthStart
      );

      const avgScore =
        completedScans.length > 0
          ? Math.round(
              completedScans.reduce((sum, s) => sum + (s.overall_score ?? 0), 0) /
                completedScans.length
            )
          : 0;

      const avgScoreThisMonth =
        scansThisMonth.length > 0
          ? Math.round(
              scansThisMonth.reduce((sum, s) => sum + (s.overall_score ?? 0), 0) /
                scansThisMonth.length
            )
          : 0;

      const avgScoreLastMonth =
        scansLastMonth.length > 0
          ? Math.round(
              scansLastMonth.reduce((sum, s) => sum + (s.overall_score ?? 0), 0) /
                scansLastMonth.length
            )
          : 0;

      const totalIssues = completedScans.reduce((sum, s) => sum + s.issues_found, 0);
      const totalCritical = completedScans.reduce((sum, s) => sum + s.critical_issues, 0);
      const totalQuickWins = completedScans.reduce((sum, s) => sum + s.quick_wins, 0);

      const scoreTrendDelta =
        avgScoreLastMonth > 0 ? avgScoreThisMonth - avgScoreLastMonth : 0;
      const scansTrendDelta =
        scansLastMonth.length > 0
          ? Math.round(
              ((scansThisMonth.length - scansLastMonth.length) /
                scansLastMonth.length) *
                100
            )
          : scansThisMonth.length > 0
          ? 100
          : 0;

      const stats: DashboardStats = {
        total_scans: scansThisMonth.length,
        avg_score: avgScore,
        total_issues: totalIssues,
        critical_issues: totalCritical,
        estimated_revenue_impact: Math.round(totalQuickWins * 125),
        score_trend: scoreTrendDelta,
        scans_trend: scansTrendDelta,
        quick_wins: totalQuickWins,
      };

      // ── Score Trend (last 4 weeks) ────────────────────────────

      const fourWeeksAgo = new Date(now.getTime() - 28 * 24 * 60 * 60 * 1000);
      const recentForTrend = completedScans.filter(
        (s) => new Date(s.created_at) >= fourWeeksAgo
      );

      const weekBuckets = new Map<number, number[]>(); // weekIndex → scores[]
      for (const scan of recentForTrend) {
        const scanDate = new Date(scan.created_at);
        const diffMs = now.getTime() - scanDate.getTime();
        const weekIndex = 3 - Math.min(3, Math.floor(diffMs / (1000 * 60 * 60 * 24 * 7)));
        const existing = weekBuckets.get(weekIndex) ?? [];
        if (scan.overall_score !== null) {
          existing.push(scan.overall_score);
          weekBuckets.set(weekIndex, existing);
        }
      }

      const WEEK_LABELS = ["3w ago", "2w ago", "1w ago", "This week"];
      const scoreTrend: ScoreTrendPoint[] = WEEK_LABELS.map((label, idx) => {
        const scores = weekBuckets.get(idx) ?? [];
        const avg =
          scores.length > 0
            ? Math.round(scores.reduce((s, v) => s + v, 0) / scores.length)
            : 0;
        return { week: label, score: avg };
      }).filter((p) => p.score > 0);

      // ── Score Distribution ────────────────────────────────────

      const RANGES = ["0-20", "21-40", "41-60", "61-80", "81-100"];
      const distributionMap = new Map<string, number>(RANGES.map((r) => [r, 0]));

      for (const scan of completedScans) {
        if (scan.overall_score !== null) {
          const bucket = scoreToRange(scan.overall_score);
          distributionMap.set(bucket, (distributionMap.get(bucket) ?? 0) + 1);
        }
      }

      const scoreDistribution: ScoreDistributionBucket[] = RANGES.map((range) => ({
        range,
        count: distributionMap.get(range) ?? 0,
        fill: getBucketFill(range),
      }));

      // ── Top Quick Wins from latest completed scan ─────────────

      let topQuickWins: (Finding & { pillar: string })[] = [];

      if (latestScanId) {
        const { data: resultsData } = await supabase
          .from("scan_results")
          .select("*")
          .eq("scan_id", latestScanId);

        if (resultsData && resultsData.length > 0) {
          const allFindings: (Finding & { pillar: string })[] = (
            resultsData as ScanResultRow[]
          ).flatMap((r) =>
            (r.findings ?? [])
              .filter((f: DbFinding) => f.severity !== "passed" && f.effort === "quick")
              .map((f: DbFinding) => ({
                id: f.id,
                title: f.title,
                severity: f.severity,
                current_state: f.current_state,
                recommendation: f.recommendation,
                ai_suggestion: f.ai_suggestion,
                is_premium: f.is_premium,
                effort: f.effort,
                estimated_lift: f.estimated_lift,
                category: f.category,
                pillar: r.pillar,
              }))
          );

          topQuickWins = allFindings
            .sort((a, b) => {
              const liftA = parseFloat(a.estimated_lift.match(/[\d.]+/)?.[0] ?? "0");
              const liftB = parseFloat(b.estimated_lift.match(/[\d.]+/)?.[0] ?? "0");
              return liftB - liftA;
            })
            .slice(0, 3);
        }
      }

      return {
        stats,
        recentScans,
        scoreTrend,
        scoreDistribution,
        topQuickWins,
        latestScanId,
      };
    },
    enabled: !!user?.id,
    staleTime: 1000 * 60 * 2, // 2 minutes
  });
}

