const Reports = () => {
  const navigate = useNavigate();
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState("all");
  const [scoreFilter, setScoreFilter] = useState("all");
  const [sortBy, setSortBy] = useState("newest");

  const { data: scans = [], isLoading } = useScans();
  const deleteScan = useDeleteScan();

  const filtered = useMemo(() => {
    let list = [...scans];

    // Search — matches URL, hostname, and page title
    if (search) {
      const q = search.toLowerCase();
      list = list.filter(
        (s) =>
          s.url.toLowerCase().includes(q) ||
          (s.page_title?.toLowerCase().includes(q) ?? false)
      );
    }

    // Status filter
    if (statusFilter !== "all") {
      list = list.filter((s) => s.status === statusFilter);
    }

    // Score filter
    if (scoreFilter !== "all") {
      list = list.filter((s) => {
        if (s.overall_score === null) return false;
        if (scoreFilter === "poor") return s.overall_score < 40;
        if (scoreFilter === "average") return s.overall_score >= 40 && s.overall_score < 70;
        if (scoreFilter === "good") return s.overall_score >= 70;
        return true;
      });
    }

    // Sort
    list.sort((a, b) => {
      if (sortBy === "newest") return new Date(b.created_at).getTime() - new Date(a.created_at).getTime();
      if (sortBy === "oldest") return new Date(a.created_at).getTime() - new Date(b.created_at).getTime();
      if (sortBy === "score-high") return (b.overall_score ?? 0) - (a.overall_score ?? 0);
      if (sortBy === "score-low") return (a.overall_score ?? 0) - (b.overall_score ?? 0);
      return 0;
    });

    return list;
  }, [scans, search, statusFilter, scoreFilter, sortBy]);

  const handleDelete = (scanId: string, hostname: string) => {
    if (!window.confirm(`Delete the scan for ${hostname}? This cannot be undone.`)) return;
    deleteScan.mutate(scanId, {
      onSuccess: () => toast.success("Scan deleted"),
      onError: () => toast.error("Failed to delete scan"),
    });
  };

  return (
    <PageTransition>
      <div className="space-y-6">
        <PageHeader title="My Reports" description="View and manage your CRO audit reports">
          <Button asChild>
            <Link to="/scan">
              <ScanLine className="mr-2 h-4 w-4" />
              New Scan
            </Link>
          </Button>
        </PageHeader>

        {/* Filters */}
        <div className="flex flex-wrap gap-3">
          <div className="relative flex-1 min-w-[200px]">
            <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
            <Input
              placeholder="Search by URL..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="pl-9 border-slate-200"
            />
          </div>
          <Select value={statusFilter} onValueChange={setStatusFilter}>
            <SelectTrigger className="w-36 border-slate-200">
              <SelectValue placeholder="Status" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Status</SelectItem>
              <SelectItem value="completed">Completed</SelectItem>
              <SelectItem value="analyzing">Analyzing</SelectItem>
              <SelectItem value="failed">Failed</SelectItem>
            </SelectContent>
          </Select>
          <Select value={scoreFilter} onValueChange={setScoreFilter}>
            <SelectTrigger className="w-36 border-slate-200">
              <SelectValue placeholder="Score" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Scores</SelectItem>
              <SelectItem value="poor">Poor (0-40)</SelectItem>
              <SelectItem value="average">Average (40-70)</SelectItem>
              <SelectItem value="good">Good (70+)</SelectItem>
            </SelectContent>
          </Select>
          <Select value={sortBy} onValueChange={setSortBy}>
            <SelectTrigger className="w-36 border-slate-200">
              <SelectValue placeholder="Sort" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="newest">Newest First</SelectItem>
              <SelectItem value="oldest">Oldest First</SelectItem>
              <SelectItem value="score-high">Score: High-Low</SelectItem>
              <SelectItem value="score-low">Score: Low-High</SelectItem>
            </SelectContent>
          </Select>
        </div>

        {/* Report Cards Grid */}
        {isLoading ? (
          <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3">
            {[1, 2, 3, 4, 5, 6].map((i) => <ReportCardSkeleton key={i} />)}
          </div>
        ) : filtered.length > 0 ? (
          <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3">
            {filtered.map((scan) => {
              let hostname = scan.url;
              try { hostname = new URL(scan.url).hostname; } catch { /* keep raw */ }

              return (
                <Link key={scan.id} to={`/reports/${scan.id}`}>
                  <Card className="h-full border-slate-200 shadow-none hover:border-primary/30 hover:shadow-sm transition-all cursor-pointer">
                    <CardContent className="p-5">
                      {/* URL + menu */}
                      <div className="flex items-start justify-between">
                        <div className="flex items-center gap-2 min-w-0">
                          <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-slate-100">
                            <span className="text-xs font-bold text-slate-400">
                              {hostname.charAt(0).toUpperCase()}
