/** Basic URL validation — checks structure, not reachability */
function isValidUrl(str: string): boolean {
  try {
    const url = new URL(str.startsWith("http") ? str : `https://${str}`);
    return url.protocol === "https:" || url.protocol === "http:";
  } catch {
    return false;
  }
}

/** Normalize URL: prepend https:// if missing */
function normalizeUrl(str: string): string {
  const trimmed = str.trim();
  if (!trimmed) return trimmed;
  if (/^https?:\/\//i.test(trimmed)) return trimmed;
  return `https://${trimmed}`;
}

// ── Map scan status to step index ───────────────────────────────

function statusToStep(status: string): number {
  switch (status) {
    case "pending": return 0;
    case "analyzing": return 3;
    case "completed": return SCAN_STEPS.length;
    case "failed": return -1;
    default: return 0;
  }
}

const Scan = () => {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const [rawUrl, setRawUrl] = useState(searchParams.get("url") || "");
  const [pageType, setPageType] = useState<PageType>(
    (searchParams.get("type") as PageType) || "landing"
  );
  const [urlError, setUrlError] = useState<string | null>(null);

  // activeScanId drives the polling query
  const [activeScanId, setActiveScanId] = useState<string | null>(null);
  const [simulatedStep, setSimulatedStep] = useState(-1);

  const inputId = useId();
  const { profile } = useAuth();
  const createScan = useCreateScan();

  const scansUsed = profile?.scans_used ?? 0;
  const scanLimit = profile?.scan_limit ?? 3;
  const scansRemaining = scanLimit - scansUsed;
  const atLimit = scansRemaining <= 0;

  // Poll the scan row while it's pending/analyzing
  const { data: pollingScan } = useScan(activeScanId ?? undefined, {
    refetchInterval: activeScanId ? 2000 : false,
  });

  const isAnalyzing = activeScanId !== null;
  const normalizedUrl = normalizeUrl(rawUrl);

  const totalSteps = SCAN_STEPS.length;
  const currentStep = isAnalyzing
    ? pollingScan
      ? statusToStep(pollingScan.status)
      : simulatedStep
    : -1;
  const progressPercent = currentStep < 0 ? 0 : Math.round(((currentStep + 1) / totalSteps) * 100);

  // When polling finds a completed/failed scan, navigate or show error
  useEffect(() => {
    if (!pollingScan) return;
    if (pollingScan.status === "completed") {
      setTimeout(() => navigate(`/reports/${pollingScan.id}`), 600);
    } else if (pollingScan.status === "failed") {
      setActiveScanId(null);
      setSimulatedStep(-1);
      toast.error("Scan failed. Please try again.", {
        action: { label: "Retry", onClick: () => startAnalysis() },
      });
    }
  }, [pollingScan?.status]);

  // Simulate step progression while waiting for the edge function
  useEffect(() => {
    if (!isAnalyzing || !activeScanId) return;
    if (pollingScan?.status === "completed" || pollingScan?.status === "failed") return;
    if (simulatedStep >= totalSteps - 1) return;

    const durations = [900, 1400, 1200, 1100, 1300, 1000, 1600];
    const timer = setTimeout(
      () => setSimulatedStep((prev) => prev + 1),
      durations[simulatedStep] ?? 1200
    );
    return () => clearTimeout(timer);
  }, [isAnalyzing, activeScanId, simulatedStep, pollingScan?.status]);

  const startAnalysis = useCallback(() => {
    setUrlError(null);
    if (!rawUrl.trim()) {
      setUrlError("Please enter a URL.");
      return;
    }
    if (!isValidUrl(normalizedUrl)) {
      setUrlError("Enter a valid URL like https://example.com/page");
      return;
    }
    if (atLimit) return;

    setSimulatedStep(0);

    createScan.mutate(
      { url: normalizedUrl, page_type: pageType },
      {
        onSuccess: (scan) => {
          setActiveScanId(scan.id);
        },
        onError: (err: unknown) => {
          setSimulatedStep(-1);
          const message = err instanceof Error ? err.message : "Failed to start scan";
          toast.error(message);
        },
      }
    );
  }, [rawUrl, normalizedUrl, pageType, atLimit, createScan]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    startAnalysis();
  };

  // ── Analysis Progress View ──────────────────────────────────
  if (isAnalyzing) {
    let hostname = rawUrl;
    try { hostname = new URL(normalizedUrl).hostname; } catch { /* keep raw */ }

    const displayStep = Math.max(0, currentStep);

    return (
      <PageTransition>
        <div className="mx-auto max-w-2xl space-y-6">
          <div>
            <h2 className="text-[28px] font-bold text-foreground">Analyzing your page</h2>
            <p className="mt-1 text-sm text-muted-foreground">
              Scanning <span className="font-medium text-foreground">{hostname}</span> — this usually takes 20-40 seconds
            </p>
          </div>

          {/* Progress bar */}
          <div className="space-y-1.5">
            <div className="flex items-center justify-between text-sm">
              <span className="text-muted-foreground">
                Step {Math.min(displayStep + 1, totalSteps)} of {totalSteps}
              </span>
              <span className="tabular-nums font-medium text-foreground">{Math.min(progressPercent, 100)}%</span>
            </div>
            <Progress value={Math.min(progressPercent, 100)} className="h-2" />
          </div>

          {/* Browser frame */}
          <BrowserFrame url={normalizedUrl}>
            <div className="relative flex h-52 items-center justify-center bg-gradient-to-br from-slate-50 via-white to-slate-50">
              {/* Scanning animation */}
              <div className="absolute inset-x-0 top-0 h-1 overflow-hidden">
                <div className="h-full w-1/3 animate-[shimmer_1.5s_ease-in-out_infinite] bg-gradient-to-r from-transparent via-primary/30 to-transparent" />
              </div>
              <div className="text-center">
                <Loader2 className="mx-auto mb-3 h-8 w-8 animate-spin text-primary" />
                <p className="text-sm font-medium text-muted-foreground">
                  {displayStep < totalSteps ? SCAN_STEPS[displayStep]?.label : "Finalizing report"}...
                </p>
              </div>
            </div>
          </BrowserFrame>

          {/* Timeline */}
          <Card className="border-slate-200 shadow-none">
            <CardContent className="p-6">
              <ScanProgressTimeline steps={SCAN_STEPS} currentStep={displayStep} />
            </CardContent>
          </Card>
        </div>
      </PageTransition>
    );
  }

  // ── URL Input Form ──────────────────────────────────────────
  return (
    <PageTransition>
      <div className="mx-auto max-w-2xl space-y-8">
        <div className="text-center">
          <h2 className="text-[28px] font-bold text-foreground">Analyze your page</h2>
          <p className="mt-2 text-muted-foreground">
            Enter any URL to get a detailed CRO audit with actionable recommendations
          </p>
        </div>

        {/* URL Input Card */}
        <Card className="border-slate-200 shadow-none">
          <CardContent className="p-8">
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <label htmlFor={inputId} className="mb-1.5 block text-sm font-medium text-foreground">
                  Page URL
                </label>
                <div className="relative">
                  <Globe className="absolute left-4 top-1/2 h-4.5 w-4.5 -translate-y-1/2 text-slate-400" />
                  <Input
                    id={inputId}
                    type="text"
                    placeholder="example.com/landing-page"
                    value={rawUrl}
                    onChange={(e) => { setRawUrl(e.target.value); setUrlError(null); }}
                    className={cn(
                      "h-14 rounded-xl border-slate-200 bg-white pl-11 pr-5 text-base placeholder:text-slate-400 focus-visible:border-primary focus-visible:ring-primary/20",
                      urlError && "border-red-300 focus-visible:border-red-400 focus-visible:ring-red-400/20"
                    )}
                  />
                </div>
                {urlError && (
                  <p className="mt-1.5 flex items-center gap-1 text-sm text-red-600">
                    <AlertCircle className="h-3.5 w-3.5" />
                    {urlError}
                  </p>
                )}
              </div>

              <div>
                <label className="mb-1.5 block text-sm font-medium text-foreground">Page type</label>
                <Select value={pageType} onValueChange={(v) => setPageType(v as PageType)}>
                  <SelectTrigger className="h-12 rounded-xl border-slate-200 bg-white">
                    <SelectValue placeholder="Select page type" />
                  </SelectTrigger>
                  <SelectContent>
                    {PAGE_TYPES.map((type) => (
                      <SelectItem key={type.value} value={type.value}>
                        {type.label}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
                <p className="mt-1 text-xs text-muted-foreground">
                  Page type affects how we weight each CRO pillar in the overall score
                </p>
              </div>

              <Button
                type="submit"
                className="h-14 w-full rounded-xl text-base font-semibold"
                disabled={!rawUrl.trim() || atLimit || createScan.isPending}
              >
                {atLimit ? (
                  "Scan limit reached — Upgrade to continue"
                ) : createScan.isPending ? (
                  <>
                    <Loader2 className="mr-2 h-5 w-5 animate-spin" />
                    Starting scan...
                  </>
                ) : (
                  <>
                    <ScanLine className="mr-2 h-5 w-5" />
                    Start Analysis
                  </>
                )}
              </Button>
            </form>

            {/* Usage indicator */}
            <div className="mt-4 flex items-center justify-center gap-4 text-xs text-muted-foreground">
              <span className="flex items-center gap-1">
                {atLimit ? (
                  <AlertCircle className="h-3.5 w-3.5 text-red-500" />
                ) : scansRemaining === 1 ? (
                  <AlertCircle className="h-3.5 w-3.5 text-amber-500" />
                ) : (
                  <Info className="h-3.5 w-3.5" />
                )}
                {scansUsed}/{scanLimit} scans used this month
              </span>
              <span>&middot;</span>
              <span>~30 seconds per scan</span>
            </div>
          </CardContent>
        </Card>

        {/* What we analyze */}
        <div>
          <h3 className="mb-4 text-center text-xs font-semibold uppercase tracking-widest text-muted-foreground">
            7 pillars we analyze
          </h3>
          <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-4">
            {CRO_PILLARS.map((pillar) => {
              const Icon = pillar.icon;
              return (
                <Card
                  key={pillar.key}
                  className="group border-slate-200 shadow-none hover:border-primary/30 hover:shadow-sm transition-all"
                >
                  <CardContent className="flex flex-col items-center p-4 text-center">
                    <div className="mb-2.5 flex h-9 w-9 items-center justify-center rounded-lg bg-primary/10 group-hover:bg-primary/15 transition-colors">
                      <Icon className="h-4 w-4 text-primary" />
                    </div>
                    <p className="text-xs font-medium text-foreground leading-tight">
                      {pillar.label}
                    </p>
                    <p className="mt-1 text-[10px] leading-snug text-muted-foreground">
                      {Math.round(pillar.weight * 100)}% weight
                    </p>
                  </CardContent>
                </Card>
              );
            })}
          </div>
        </div>

        {/* How scoring works */}
        <Card className="border-slate-200 bg-slate-50/50 shadow-none">
          <CardContent className="p-5">
            <div className="flex items-start gap-3">
              <Info className="mt-0.5 h-4 w-4 shrink-0 text-muted-foreground" />
              <div className="text-xs text-muted-foreground leading-relaxed">
                <span className="font-medium text-foreground">How scoring works:</span> Each pillar is scored 0-100 based on specific checks.
                Pillar weights vary by page type — for example, CTA Effectiveness is weighted 22% on landing pages but only 12% on blog posts.
                Your overall score is a weighted average compared against industry benchmarks.
              </div>
            </div>
          </CardContent>
        </Card>
      </div>
    </PageTransition>
  );
};

