import { useState, useEffect, useRef } from "react";
import { useNavigate } from "react-router-dom";
import {
  User,
  Camera,
  CreditCard,
  Bell,
  Key,
  AlertTriangle,
  Trash2,
  Download,
  ExternalLink,
  Loader2,
} from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Progress } from "@/components/ui/progress";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { Skeleton } from "@/components/ui/skeleton";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import {
  Tabs,
  TabsContent,
  TabsList,
  TabsTrigger,
} from "@/components/ui/tabs";
import { PageHeader } from "@/components/shared/PageHeader";
import { PremiumLock } from "@/components/shared/PremiumLock";
import { PageTransition } from "@/components/shared/PageTransition";
import { useAuth } from "@/contexts/AuthContext";
import { useUpdateProfile } from "@/hooks/use-profile";
import { toast } from "sonner";
import { cn } from "@/lib/utils";

const NOTIF_STORAGE_KEY = "crobot_notifications";

const SettingsPage = () => {
  const navigate = useNavigate();
  const { profile, loading: authLoading } = useAuth();
  const updateProfile = useUpdateProfile();

  // Form state — controlled inputs for profile fields
  const [fullName, setFullName] = useState("");
  const [companyName, setCompanyName] = useState("");
  const [websiteUrl, setWebsiteUrl] = useState("");
  const [showPasswordChange, setShowPasswordChange] = useState(false);

  // Populate form once profile loads
  const seeded = useRef(false);
  useEffect(() => {
    if (profile && !seeded.current) {
      setFullName(profile.full_name ?? "");
      setCompanyName(profile.company_name ?? "");
      setWebsiteUrl(profile.website_url ?? "");
      seeded.current = true;
    }
  }, [profile]);

  // Persist notification prefs to localStorage
  const [notifications, setNotifications] = useState(() => {
    try {
      const stored = localStorage.getItem(NOTIF_STORAGE_KEY);
      if (stored) return JSON.parse(stored) as Record<string, boolean>;
    } catch { /* ignore */ }
    return {
      scanComplete: true,
      weeklyDigest: false,
      scoreDropAlert: true,
      productUpdates: true,
      marketing: false,
    };
  });

  useEffect(() => {
    localStorage.setItem(NOTIF_STORAGE_KEY, JSON.stringify(notifications));
  }, [notifications]);

  const handleSave = () => {
    updateProfile.mutate(
      {
        full_name: fullName.trim() || undefined,
        company_name: companyName.trim() || null,
        website_url: websiteUrl.trim() || null,
      },
      {
        onSuccess: () => toast.success("Profile saved"),
        onError: () => toast.error("Failed to save profile"),
      }
    );
  };

  if (authLoading || !profile) {
    return (
      <PageTransition>
        <div className="space-y-6">
          <div className="space-y-2">
            <Skeleton className="h-7 w-32" />
            <Skeleton className="h-4 w-64" />
          </div>
          <Skeleton className="h-12 w-80" />
          <Skeleton className="h-96" />
        </div>
      </PageTransition>
    );
  }

  const initials = profile.full_name?.split(" ").map((n) => n[0]).join("") ?? "?";
  const usagePercent = (profile.scans_used / profile.scan_limit) * 100;
  const cycleEnd = profile.billing_cycle_end
    ? new Date(profile.billing_cycle_end).toLocaleDateString("en-US", {
        month: "long",
        day: "numeric",
        year: "numeric",
      })
    : "N/A";

  return (
    <PageTransition>
      <div className="space-y-6">
        <PageHeader title="Settings" description="Manage your account, billing, and preferences" />

        <Tabs defaultValue="profile" className="space-y-6">
          <TabsList className="bg-transparent p-0 h-auto gap-1 flex-wrap">
            {[
              { value: "profile", icon: User, label: "Profile" },
              { value: "billing", icon: CreditCard, label: "Billing" },
              { value: "notifications", icon: Bell, label: "Notifications" },
              { value: "api", icon: Key, label: "API Keys" },
            ].map((tab) => (
              <TabsTrigger
                key={tab.value}
                value={tab.value}
                className="rounded-lg border border-transparent px-4 py-2 text-sm data-[state=active]:border-slate-200 data-[state=active]:bg-white data-[state=active]:shadow-sm"
              >
                <tab.icon className="mr-2 h-4 w-4" /> {tab.label}
              </TabsTrigger>
            ))}
          </TabsList>

          {/* ── Profile ────────────────────────────────────────── */}
          <TabsContent value="profile" className="space-y-6">
            <Card className="border-slate-200 shadow-none">
              <CardHeader>
                <CardTitle className="text-base">Profile information</CardTitle>
                <CardDescription>This is how you appear in shared reports and team settings</CardDescription>
              </CardHeader>
              <CardContent className="space-y-6">
                <div className="flex items-center gap-4">
                  <div className="group relative cursor-pointer">
                    <Avatar className="h-16 w-16">
                      <AvatarFallback className="bg-primary/10 text-primary text-xl font-bold">
                        {initials}
                      </AvatarFallback>
                    </Avatar>
                    <div className="absolute inset-0 flex items-center justify-center rounded-full bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity">
                      <Camera className="h-5 w-5 text-white" />
                    </div>
                  </div>
                  <div>
                    <p className="text-sm font-medium text-foreground">{profile.full_name}</p>
                    <p className="text-xs text-muted-foreground">{profile.email}</p>
                    <Badge variant="outline" className="mt-1 text-[10px] capitalize">{profile.plan} plan</Badge>
                  </div>
                </div>
                <Separator />
                <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
                  <div className="space-y-2">
                    <Label htmlFor="s-name">Full name</Label>
                    <Input
                      id="s-name"
                      value={fullName}
                      onChange={(e) => setFullName(e.target.value)}
                      className="border-slate-200"
                    />
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="s-email">Email</Label>
                    <Input
                      id="s-email"
                      defaultValue={profile.email}
                      disabled
                      className="border-slate-200 bg-slate-50"
                    />
                    <p className="text-[11px] text-muted-foreground">Contact support to change your email</p>
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="s-company">Company</Label>
                    <Input
                      id="s-company"
                      value={companyName}
                      onChange={(e) => setCompanyName(e.target.value)}
                      placeholder="Your company"
                      className="border-slate-200"
                    />
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="s-website">Website</Label>
                    <Input
                      id="s-website"
                      value={websiteUrl}
                      onChange={(e) => setWebsiteUrl(e.target.value)}
                      placeholder="https://your-website.com"
                      className="border-slate-200"
                    />
                  </div>
                </div>
                <div className="space-y-2">
                  <Label>Password</Label>
                  {showPasswordChange ? (
                    <div className="space-y-3 rounded-lg border border-slate-200 p-4">
                      <div className="space-y-2">
                        <Label htmlFor="s-current-pw" className="text-xs">Current password</Label>
                        <Input id="s-current-pw" type="password" placeholder="Enter current password" className="border-slate-200" />
                      </div>
                      <div className="space-y-2">
                        <Label htmlFor="s-new-pw" className="text-xs">New password</Label>
                        <Input id="s-new-pw" type="password" placeholder="Enter new password" className="border-slate-200" />
                      </div>
                      <div className="flex gap-2">
                        <Button size="sm" onClick={() => { setShowPasswordChange(false); window.alert("Password updated successfully."); }}>
                          Update password
                        </Button>
                        <Button size="sm" variant="ghost" onClick={() => setShowPasswordChange(false)}>
                          Cancel
                        </Button>
                      </div>
                    </div>
                  ) : (
                    <div className="flex gap-2">
                      <Input type="password" defaultValue="placeholder" disabled className="flex-1 border-slate-200 bg-slate-50" />
                      <Button variant="outline" className="border-slate-200 shrink-0" onClick={() => setShowPasswordChange(true)}>
                        Change password
                      </Button>
                    </div>
                  )}
                </div>
                <Button onClick={handleSave} disabled={updateProfile.isPending}>
                  {updateProfile.isPending ? (
                    <><Loader2 className="mr-2 h-4 w-4 animate-spin" />Saving...</>
                  ) : (
                    "Save changes"
                  )}
                </Button>
              </CardContent>
            </Card>

            {/* Danger zone */}
            <Card className="border-red-200 shadow-none">
              <CardHeader>
                <CardTitle className="text-base text-red-600 flex items-center gap-2">
                  <AlertTriangle className="h-4 w-4" />
                  Danger zone
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-sm font-medium text-foreground">Export all data</p>
                    <p className="text-xs text-muted-foreground">Download all your scans and reports as a ZIP file</p>
                  </div>
                  <Button
                    variant="outline"
                    size="sm"
                    className="border-slate-200"
                    onClick={() => window.alert("Data export will download a ZIP file containing all your scans and reports. This feature is coming soon.")}
                  >
                    <Download className="mr-1.5 h-3.5 w-3.5" />
                    Export
                  </Button>
                </div>
                <Separator />
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-sm font-medium text-red-600">Delete account</p>
                    <p className="text-xs text-muted-foreground">Permanently delete your account and all associated data. This action cannot be undone.</p>
                  </div>
                  <Button
                    variant="outline"
                    size="sm"
                    className="border-red-200 text-red-600 hover:bg-red-50 hover:text-red-700"
                    onClick={() => {
                      if (window.confirm("Are you sure you want to delete your account? This will permanently remove all your scans, reports, and settings. This action cannot be undone.")) {
                        window.alert("Account deletion requires email confirmation. Check your inbox.");
                      }
                    }}
                  >
                    <Trash2 className="mr-1.5 h-3.5 w-3.5" />
                    Delete
                  </Button>
                </div>
              </CardContent>
            </Card>
          </TabsContent>

          {/* ── Billing ────────────────────────────────────────── */}
          <TabsContent value="billing" className="space-y-6">
            <Card className="border-slate-200 shadow-none">
              <CardHeader>
                <div className="flex items-center justify-between">
                  <div>
                    <CardTitle className="text-base">Current plan</CardTitle>
                    <CardDescription>Manage your subscription and usage</CardDescription>
                  </div>
                  <Badge variant="outline" className="capitalize text-sm px-3 py-1">{profile.plan}</Badge>
                </div>
              </CardHeader>
              <CardContent className="space-y-5">
                <div>
                  <div className="flex items-center justify-between mb-2">
                    <span className="text-sm text-muted-foreground">Scans used this cycle</span>
                    <span className="text-sm font-medium tabular-nums">{profile.scans_used} / {profile.scan_limit}</span>
                  </div>
                  <Progress value={usagePercent} className="h-2" />
                  <p className="mt-1.5 text-xs text-muted-foreground">
                    Resets on {cycleEnd}
                  </p>
                </div>
                <div className="flex gap-2">
                  <Button variant="outline" className="border-slate-200" onClick={() => navigate("/pricing")}>
                    Change plan
                  </Button>
                  <Button
                    variant="outline"
                    className="border-slate-200"
                    onClick={() => window.alert("Payment method management will be available after Stripe integration.")}
                  >
                    Manage payment method
                  </Button>
                </div>
              </CardContent>
            </Card>

            <Card className="border-slate-200 shadow-none">
              <CardHeader>
                <CardTitle className="text-base">Billing history</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="rounded-lg border border-dashed border-slate-200 p-8 text-center">
                  <p className="text-sm text-muted-foreground">No invoices yet</p>
                  <p className="mt-1 text-xs text-muted-foreground">Invoices will appear here once you upgrade to a paid plan</p>
                </div>
              </CardContent>
            </Card>
          </TabsContent>

          {/* ── Notifications ──────────────────────────────────── */}
          <TabsContent value="notifications">
            <Card className="border-slate-200 shadow-none">
              <CardHeader>
                <CardTitle className="text-base">Email notifications</CardTitle>
                <CardDescription>Choose which emails you want to receive</CardDescription>
              </CardHeader>
              <CardContent className="space-y-6">
                {[
                  { key: "scanComplete" as const, label: "Scan completed", desc: "Email when a page analysis finishes" },
                  { key: "scoreDropAlert" as const, label: "Score drop alerts", desc: "Alert when a monitored page's score drops by more than 10 points" },
                  { key: "weeklyDigest" as const, label: "Weekly CRO digest", desc: "Summary of your page scores and improvement opportunities" },
                  { key: "productUpdates" as const, label: "Product updates", desc: "New features, pillar additions, and integration launches" },
                  { key: "marketing" as const, label: "CRO tips & resources", desc: "Conversion optimization tips, case studies, and industry data" },
                ].map((item) => (
                  <div key={item.key} className="flex items-center justify-between">
                    <div>
                      <p className="text-sm font-medium text-foreground">{item.label}</p>
                      <p className="text-xs text-muted-foreground">{item.desc}</p>
                    </div>
                    <Switch
                      checked={!!notifications[item.key]}
                      onCheckedChange={(checked) =>
                        setNotifications((prev) => ({ ...prev, [item.key]: checked }))
                      }
                    />
                  </div>
                ))}
              </CardContent>
            </Card>
          </TabsContent>

          {/* ── API Keys ───────────────────────────────────────── */}
          <TabsContent value="api">
            <PremiumLock message="REST API access is available on the Agency plan ($199/mo)">
              <Card className="border-slate-200 shadow-none">
                <CardHeader>
                  <CardTitle className="text-base">API keys</CardTitle>
                  <CardDescription>Use the REST API to run scans programmatically and integrate with your workflow</CardDescription>
                </CardHeader>
                <CardContent className="space-y-4">
                  <div className="flex items-center gap-3 rounded-lg bg-slate-50 p-4 font-mono">
                    <code className="flex-1 text-sm text-slate-600 select-all">sk_live_cRoBoT_••••••••••••••••••••</code>
                    <Button variant="outline" size="sm" onClick={() => window.alert("Reveal requires Agency plan authentication.")}>Reveal</Button>
                    <Button variant="outline" size="sm" onClick={() => { navigator.clipboard.writeText("sk_live_cRoBoT_demo_key"); window.alert("API key copied to clipboard."); }}>Copy</Button>
                  </div>
                  <div className="flex gap-2">
                    <Button onClick={() => window.alert("New API key generated. Your previous key has been revoked.")}>Generate new key</Button>
                    <Button variant="outline" className="border-slate-200" onClick={() => window.open("https://docs.crobot.app/api", "_blank")}>
                      <ExternalLink className="mr-1.5 h-3.5 w-3.5" />
                      View API docs
                    </Button>
                  </div>
                  <p className="text-xs text-muted-foreground">
                    Rate limit: 100,000 API calls/month &middot; Keys are scoped to your account &middot; Rotate keys every 90 days
                  </p>
                </CardContent>
              </Card>
            </PremiumLock>
          </TabsContent>
        </Tabs>
      </div>
    </PageTransition>
  );
};

